CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE execution_mode AS ENUM ('approval','automatic');
CREATE TYPE qualification_status AS ENUM ('qualified','not_qualified','already_contacted','private','inactive','personal_profile','error');
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, niche text NOT NULL, location text NOT NULL, outreach_message text NOT NULL, execution_mode execution_mode NOT NULL DEFAULT 'approval', maximum_contacts integer NOT NULL CHECK(maximum_contacts BETWEEN 1 AND 20), minimum_delay_seconds integer NOT NULL CHECK(minimum_delay_seconds >= 90), maximum_delay_seconds integer NOT NULL CHECK(maximum_delay_seconds >= minimum_delay_seconds), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE prospects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text NOT NULL, display_name text, profile_url text NOT NULL, biography text, followers_text text, detected_category text, detected_location text, qualification_score integer CHECK(qualification_score BETWEEN 0 AND 100), qualification_status qualification_status, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), do_not_contact boolean NOT NULL DEFAULT false, notes text, CONSTRAINT prospects_username_unique UNIQUE(username), CONSTRAINT prospects_url_unique UNIQUE(profile_url));
CREATE TABLE executions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid REFERENCES campaigns(id), status text NOT NULL, profiles_found integer NOT NULL DEFAULT 0, profiles_analyzed integer NOT NULL DEFAULT 0, profiles_qualified integer NOT NULL DEFAULT 0, messages_prepared integer NOT NULL DEFAULT 0, messages_sent integer NOT NULL DEFAULT 0, messages_skipped integer NOT NULL DEFAULT 0, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, error_message text);
CREATE UNIQUE INDEX only_one_running_execution ON executions ((status)) WHERE status='running';
CREATE TABLE outreach_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns(id), prospect_id uuid NOT NULL REFERENCES prospects(id), execution_id uuid NOT NULL REFERENCES executions(id), message text NOT NULL, status text NOT NULL, prepared_at timestamptz, approved_at timestamptz, sent_at timestamptz, error_message text, UNIQUE(campaign_id, prospect_id), UNIQUE(prospect_id, message));
CREATE TABLE blocklist (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE, profile_url text UNIQUE, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(username IS NOT NULL OR profile_url IS NOT NULL));
CREATE INDEX outreach_status_idx ON outreach_messages(status);
CREATE INDEX prospect_status_idx ON prospects(qualification_status);
